import logging
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable
from taf.sbts.oam.coam.admin.utils import raise_value_error
from taf.sbts.oam.coam.admin.utils.util import wrap_result
from taf.sbts.oam.coam.admin.utils.wrap_nidd import wrap_nidd_output


class PMInterface21B(object):
    def get_counters_info(self, dist_name, timeout=10, wrap_nidd=False, **kwargs):
        """
        Provide information about counters.

        :param dist_name: Dist name of counter or 'all'.
        :param int timeout: Timeout for the operation.
        :param bool wrap_nidd: When set to True returns a parsed and concise list with counter info.
                               Parameter added due to changes introduced by Admin CLI that altered regular output.
        :return dict: dict with counters info.
        More details (content of requestMessage, dist name structure):
                      https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getCounters.html
        """
        parameters = {'distName': dist_name}
        counters_info = self._api_client.execute_infomodel_request('getCounters', parameters, timeout)

        if counters_info is None:
            raise DataNotAvailable("Counters info has not been provided by M-Plane.")

        if wrap_nidd:
            wrapped = wrap_nidd_output(counters_info)
            if wrapped:
                return wrapped
            else:
                logging.debug(counters_info)
                raise DataNotAvailable("Unable to retrieve counters info from given structure.")
        else:
            return counters_info

    def get_pm_counters(self, counter_ids="", timeout=60, wrap_nidd=False, **kwargs):
        """
        Provide information about counters.

        :param counter_ids: Counter IDs (splitted by comma). Empty string matches all.
        :param int timeout: Timeout for the operation.
        :param bool wrap_nidd: When set to True returns a parsed and concise list with counter info.
                               Parameter added due to changes introduced by Admin CLI that altered regular output.
        :return dict: dict with counters info.
        More details (content of requestMessage, dist name structure):
                      https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getCounters.html
        """
        if 'couter_ids' in kwargs.keys() and not counter_ids:
            counter_ids = kwargs.get('couter_ids')
        counter_ids = counter_ids.split(",") if counter_ids else "all"
        counters_info = self._api_client.execute_infomodel_request('getCounters', {"counterIds": counter_ids}, timeout)

        if counters_info is None:
            raise DataNotAvailable("Counters info has not been provided by M-Plane.")

        if wrap_nidd:
            wrapped = wrap_nidd_output(counters_info)
            if wrapped:
                return wrapped
            else:
                logging.debug(counters_info)
                raise DataNotAvailable("Unable to retrieve counters info from given structure.")
        else:
            return counters_info

    def get_pm_files(self, local_file_path, timeout=10):
        """
        Get information about pm files, provided by M-plane (OAM) and saves them under given path.

        :param string local_file_path: Path to save the file.
        :param Union[int, str] timeout: Keyword execution timeout.
        :raise DataNotAvailable: If files list is not provided by M-Plane.
        :return string: Path to saved file.
                        More details (content of requestMessage is returned data):
                        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getPmFiles.html
        """
        pm_files_data = self._api_client.execute_infomodel_request('getPmFiles', {}, timeout)

        if pm_files_data is None:
            raise DataNotAvailable("Pm Files list has not been provided by M-Plane")

        self._save_content_to_file(pm_files_data, local_file_path)
        return local_file_path

    def _save_content_to_file(self, content, full_path):
        with open(full_path, 'w') as target_file:
            target_file.write(content)

    @wrap_result
    def get_kpi(self, object_name="", kpi_id="", timeout=60):
        """Get KPI.

        :param string object_name: (Optional) The object from which the KPI value was calculated.
        :param string kpi_id: (Optional) The id of a kpi returns the value only for this particular kpi.
        :param Union[int, str] timeout: Keyword execution timeout.
        :raise DataNotAvailable: If KPI object is not provided by M-Plane.
        :return AdminApiObject: returns the values for all the KPIs

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getKpi.html
        """

        kpi = self._api_client.execute_infomodel_request("getKpi", {"object": object_name, "id": kpi_id}, timeout)

        if kpi is None:
            raise DataNotAvailable('KPI object has not been provided by M-Plane')

        return kpi

    def get_measurements(self, measurement_type="all", timeout=60, **kwargs):
        """
        Get measurements.

        :param string measurement_type: Type of measurement <"systemLoad" | "realTime" | "all">, "all" set by default.
        :param Union[int, str] timeout: Keyword execution timeout.
        :raise DataNotAvailable: If measurements list is not provided by M-Plane.
        :return list: list of dicts where dict is one measurement.
        :raises: ValueError if measurement_type does not meet one of the given values.

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getMeasurements.html
        """
        if measurement_type not in ("systemLoad", "realTime", "all"):
            raise_value_error(param="measurement_type",
                              value=str(measurement_type),
                              subpage="tutorial-getMeasurements.html")

        measurements = self._api_client.execute_infomodel_request('getMeasurements',
                                                                  {'type': measurement_type},
                                                                  timeout)
        if measurements is None:
            raise DataNotAvailable('Measurements list has not been provided by M-Plane')

        return measurements

    def collect_pm_files(self, target_file_name, timeout=120):
        """
        Collect PM files and save in provided path
        :param str target_file_name: target filename.
        :param int timeout: (optional) Timeout for the operation. Defaults set to 120s.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getPmFiles.html
        """

        self._api_client.execute_infomodel_request(name='getPmFiles',
                                                   parameters={},
                                                   timeout=timeout,
                                                   output_file_name=target_file_name)
